function Chat({ messages, send }) {
  const [shown, addOptimistic] = useOptimistic(
    messages,
    (current, text) => [...current, { text, sending: true }]
  );

  async function submit(formData) {
    addOptimistic(formData.get('text'));
    await send(formData);
  }
}

